const fractalPass=(ori=[100,100],relLines=[[200,0]],n=10,sw=.1,vb,pAttr,keepLnArr=true)=>{for(let i=n;i-- >0;){relLines=relLines.flatMap(x=>useFn(x,n-i))}return{svg:toSvg(ori,relLines,vb,pAttr,n<7||sw<0?"":'stroke-width="'+Math.abs(sw)+'"'),relLines:keepLnArr&&relLines}};let nScale=1.5;const l2sawZacLine=([x,y])=>{const xM=x/2,yM=y/2;const xN=nScale*-y,yN=nScale*x;return[[xM-xN,yM-yN],[2*xN,2*yN],[xM-xN,yM-yN]]};let useFn=l2sawZacLine;const toSvg=(ori,relLines,viewBox="0 0 600 800 ",pAttr='fill="none" stroke="black"',wid="")=>`<svg width="600" viewBox="${viewBox}" ${wid}><path  ${pAttr} d="m${ori[0]} ${ori[1]} l${relLines.map(([x,y])=>[x.toFixed(2),y.toFixed(2)]).join("l")}" /></svg>`;let shapes={line:[[200,0]],square:[[200,0],[0,200],[-200,0],[0,-200]],tri:[[200,0],[-100,173],[-100,-173]],blob:[[120,20],[80,60],[40,100],[-20,120],[-80,90],[-110,20],[-70,-70],[20,-100],[100,-60]],spiral:[[80,0],[40,40],[0,60],[-40,40],[-60,0],[-40,-40],[0,-60],[50,-50],[90,10]],ridge:[[100,20],[70,-40],[90,70],[60,-60],[120,40]],islands:[[80,0],[20,30],[50,-10],[10,60],[-40,20],[-70,-30],[-30,-70],[50,-20]],flame:[[80,0],[40,40],[0,60],[-40,40],[-60,0],[-40,-20],[0,-40],[50,-20],[40,10],[5,15],[10,-20],[-80,-40],[-5,-25]]};let waitTime=200;useShape=shapes.square;let pause=false;let rndSeed=(x,y=0,t=0)=>(1+Math.sin(t+x*7989.3238+y*31459.26575)%1)/2;document.body.onkeydown=ev=>pause=ev.key=="q";let sleep=ms=>new Promise(r=>setTimeout(r,ms));const showFractal=async(n,shapNm)=>{nScale=n;for(let i=0;i<10;i++){if(pause&&(pause=confirm("Really abort?")))throw Error("halt");const myFrac=fractalPass(undefined,shapes[shapNm],i);document.body.innerHTML=`<h2>Fractal</h2> <p>fn = ${useFn.name} shape = ${shapNm} depth = ${i} nScale = ${n} <kbd>PRESS [Q] pause/quit</kbd></p>`+myFrac.svg;await sleep(waitTime)}};const speacialN=[.288675,.5,.577,.707,.866,1,1.414];function moreChaos([x,y]){const xM=x/2,yM=y/2;const xN=nScale*-y,yN=nScale*x;return[[xM-xN,yM-yN],[1.3*xN,.7*yN],[xM+xN,yM+yN]]}function dragonLine([x,y]){return[[nScale*(x-y)/2,(y+x)/2],[(x+y)/2/nScale,(y-x)/2]]}function kochLine([x,y]){const a=[x/3,y/3];const cos=.5*nScale;const sin=.8660254;const rx=a[0]*cos-a[1]*sin;const ry=a[0]*sin+a[1]*cos;return[a,[rx-a[0],ry-a[1]],[a[0]-rx,a[1]-ry],a].map(p=>p.map(x=>1.5*x))}function levyLine([x,y]){return[[nScale*(x-y)/2,(x+y)/2],[(x+y)/2/nScale,(y-x)/2]]}let flip=1;function dragonAlt([x,y]){flip*=-1;return[[nScale*(x-flip*y)/2,(y+flip*x)/2],[(x+flip*y)/2/nScale,(y-flip*x)/2]]}function hexFractal([x,y]){const s=nScale;return[[x*s,y*s],[-y*s,x*s],[x*s,y*s],[y*s,-x*s],[x*s,y*s]]}function noisy([x,y]){const n=(Math.random()-.5)*nScale;const xN=-y*n;const yN=x*n;return[[x/2-xN,y/2-yN],[2*xN,2*yN],[x/2-xN,y/2-yN]]}let SEED=42;function noisySeed([x,y]){const n=(rndSeed(x,y,SEED)-.5)*nScale;const xN=-y*n;const yN=x*n;return[[x/2-xN,y/2-yN],[2*xN,2*yN],[x/2-xN,y/2-yN]]}const rules=[l2sawZacLine,moreChaos,dragonAlt];function rndRule(l){return rules[Math.random()*rules.length|0](l)}const smartRule=([x,y],depth)=>{const len=Math.hypot(x,y);const s=Math.random()*.4+.1+.4*Math.sin(depth*.7);return[[x/2+s*-y,y/2+s*x],[x/2-s*-y,y/2-s*x]]};const ridgeNoise=([x,y])=>{const len=Math.hypot(x,y);const n=(Math.sin(len*.03)+Math.random()*.7)*.35;const xN=-y*n;const yN=x*n;return[[x*.45-xN,y*.45-yN],[2*xN,2*yN],[x*.55,y*.55]]};const erosion=([x,y])=>{const n=Math.random()*nScale;return[[x*.3,y*.3],[-y*n,x*n],[x*.4,y*.4],[y*n*.5,-x*n*.5],[x*.3,y*.3]]};useFn=moreChaos;(async x=>{for(let shapNm in shapes)for(let n=.2;n<1.3;n+=.1)await showFractal(n,shapNm)})();function atlasFrac(nScaleP=.6,useFnP=noisy,depth=8,shape=shapes.tri){nScale=nScaleP;useFn=useFnP;const myFrac=fractalPass([0,0],shape,depth,.5,"-50 -50 300 300");document.body.innerHTML=`<h2> Continent/Atlas Fractal</h2>`+myFrac.svg;1;const contNt=document.querySelector("path");contNt.setAttribute("stroke","#ccd");contNt.setAttribute("fill","#cda");const svg=document.querySelector("svg");svg.style.background="#abd";svg.setAttribute("stroke-linejoin","round");return myFrac}function atlasFrac2(shape=shapes.square,n=6){useFn=erosion;nScale=.9;document.write((_resAtlas2=fractalPass(undefined,shape,n,.5,"-200 -200 800 800",'fill="#cda" stroke="#55d6"')).svg)}function starFrac(nScaleP=.6,useFnP=dragonAlt,depth=8,shape=shapes.blob){nScaleP=nScaleP;useFn=useFnP;const myFrac=fractalPass([0,0],shape,depth,1,"-50 -50 300 300");document.body.innerHTML=`<h2> Star/RND-Pnt Fractal</h2>`+myFrac.svg;1;const contNt=document.querySelector("path");contNt.setAttribute("stroke","#edb");contNt.setAttribute("fill","none");const svg=document.querySelector("svg");svg.style.background="#112";contNt.setAttribute("stroke-width","8");svg.setAttribute("stroke-linecap","round");svg.setAttribute("stroke-dasharray","0,200");return myFrac}function quadStitch(){nScale=.47888;useFn=l2sawZacLine;const myFrac=fractalPass([100,100],shapes.square,8,.05,"0 0 600 300");document.body.innerHTML=`<h2>Fractal</h2>`+myFrac.svg;1}function fireFractal(){nScale=.64;useFn=noisy;const myFrac=fractalPass([100,100],shapes.flame,5,-10,"-200 -200 500 500");document.body.innerHTML=`<h2>Fractal</h2>`+myFrac.svg;1;let path=document.querySelector("path");path.setAttribute("fill","#db3");path.setAttribute("stroke-linejoin","round");path.setAttribute("stroke-width","3");path.setAttribute("stroke-linecap","round");path.setAttribute("stroke-dasharray","5,9,3,2,100");path.setAttribute("stroke","#f50");path.parentElement.style.background="#224"}function islandFrac(){useFn=ridgeNoise;nScale=2;document.write((_res=fractalPass(undefined,shapes.square,8,3.5,"-300 -200 800 800",'fill="#5d56" stroke="#55d6" stroke-linecap="round" stroke-linejoin="bevel"  stroke-dasharray="30,20,50"')).svg)}function coolRndCont(seed){useFn=noisySeed;SEED=seed;nScale=4.8;document.write((_res=fractalPass(undefined,shapes.square,7,4,"-8000 -8000 16000 16000",' stroke-linecap="round" stroke-linejoin="bevel"  stroke-dasharray="30,20,50"')).svg)}async function CloudAnim(){document.body.innerHTML="";coolRndCont(10*Math.random());const svg=document.querySelector("svg");window.steps=1e4;for(;steps--;){await sleep(200),svg.viewBox.baseVal.x+=12*Math.random()-4,svg.viewBox.baseVal.y+=12*Math.random()-4}}
